Item.method_code:
const { item, itemNode, itemTypeName } = options;
if (!item && !itemNode) {
	return false;
}

const id = item ? item.id : itemNode.getAttribute('id');
const isNew = ArasModules.item.isNew(itemTypeName, id);
if (isNew) {
	return false;
}

const claimedById = item ? item['locked_by_id'] : aras.getItemProperty(itemNode, 'locked_by_id');
const isClaimed = Boolean(claimedById);
if (!isClaimed) {
	return false;
}

const { user } = aras;
const isClaimedByMe = claimedById === user.id;
const isAdmin = user.type === 'admin';
const canExecute = isClaimedByMe || isAdmin;

return canExecute;
